-- Bills where a commission was recorded for one dentist but the lines have no dentist: the lines get that dentist (their
-- My cases then shows the case). Only when commission is counted per payment (the default), and only one dentist per bill.
UPDATE invoice_items SET dentist_id = (SELECT e.user_id FROM dentist_commissions c JOIN employees e ON e.id = c.employee_id JOIN users u ON u.id = e.user_id AND u.role = 'dentist' WHERE c.invoice_id = invoice_items.invoice_id AND c.status = 'valid' LIMIT 1), legacy_dentist = 0, done_on = COALESCE(done_on, (SELECT substr(i.issued_at, 1, 10) FROM invoices i WHERE i.id = invoice_items.invoice_id)) WHERE dentist_id IS NULL AND NOT EXISTS (SELECT 1 FROM settings WHERE key = 'payroll.dentist_commission_basis' AND value LIKE '%procedure%') AND invoice_id IN (SELECT c.invoice_id FROM dentist_commissions c JOIN employees e ON e.id = c.employee_id JOIN users u ON u.id = e.user_id AND u.role = 'dentist' WHERE c.status = 'valid' AND c.invoice_id IS NOT NULL GROUP BY c.invoice_id HAVING COUNT(DISTINCT e.user_id) = 1)
